#!/usr/bin/env python3
"""Render project-plan.html from factual stage status in project-plan.json."""
import html
import json
from pathlib import Path
from service_matrix import service_matrix_html
ROOT=Path(__file__).resolve().parent
E=html.escape

def render():
    data=json.loads((ROOT/'project-plan.json').read_text())
    stages=data['stages']; counts={status:sum(s['status']==status for s in stages) for status in ('complete','active','pending')}
    cards=[]
    phase_by_id={phase['id']:phase for phase in data['phases']}
    prior_phase=None
    for stage in stages:
        if stage['phase'] != prior_phase:
            phase=phase_by_id[stage['phase']]
            cards.append(f'<header id="phase-{E(phase["id"])}" class="phase-head"><h2>{E(phase["title"])}</h2><p>{E(phase["description"])}</p></header>')
            prior_phase=stage['phase']
        number=stage['number']; status=stage['status']; label={'complete':'Complete','active':'In progress','pending':'Pending'}[status]
        items=''.join(f'<li>{E(x)}</li>' for x in stage['deliverables'])
        checks=''.join(f'<li class="check {"done" if x["done"] else "open"}"><span aria-hidden="true">{"✓" if x["done"] else "○"}</span><span><strong>{"Passed" if x["done"] else "To verify"}</strong> {E(x["text"])}</span></li>' for x in stage['checks'])
        cards.append(f'<article id="stage-{number}" class="stage {status}"><header><div class="number">{number:02}</div><div><h2>{E(stage["title"])}</h2><span class="badge">{label}</span></div></header><p class="goal">{E(stage["goal"])}</p><div class="columns"><div><h3>Deliverables</h3><ul>{items}</ul></div><div><h3>Acceptance gates</h3><ul class="checklist">{checks}</ul></div></div><p class="evidence"><strong>Current evidence</strong> {E(stage["evidence"])}</p></article>')
    navigation=''.join(f'<a href="#stage-{s["number"]}" class="{s["status"]}" title="{E(s["title"])}">{s["number"]:02}</a>' for s in stages)
    out='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="author" content="Krishna Kallamadi"><title>RescueRelay project plan</title><style>
:root{--forest:#183f36;--ink:#1c343b;--muted:#566d72;--line:#d8e3dd;--paper:#fff;--base:#f4f7f3}*{box-sizing:border-box}body{margin:0;background:var(--base);font:15px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif;color:var(--ink)}a{color:#14624f;text-underline-offset:3px}a:focus-visible{outline:3px solid #c38524;outline-offset:4px}.wrap{max-width:1100px;margin:auto;padding:42px 34px 70px}.mast{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:38px}.brand{font-size:23px;font-weight:750;letter-spacing:-.5px;color:var(--forest)}.mast a{font-size:13px}.eyebrow{color:#49705f;text-transform:uppercase;font-size:11px;font-weight:750;letter-spacing:1.8px}h1{font-size:clamp(34px,4.5vw,55px);line-height:1.13;letter-spacing:-1.5px;margin:13px 0 20px;max-width:800px}.lead{font-size:18px;color:var(--muted);max-width:820px}.author{font-size:13px}.table-wrap{overflow-x:auto;margin:20px 0}table{border-collapse:collapse;width:100%;min-width:780px;font-size:12px;line-height:1.5}th{text-align:left;background:#183f36;color:#fff;padding:12px}td{padding:12px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:700;width:16%}tr:nth-child(even) td{background:#f4f7f4}.service-section{margin-top:35px;padding:26px;background:white;border:1px solid var(--line);border-radius:14px}.service-section>p{font-size:14px}.phase-head{margin:44px 0 20px;padding:22px 26px;background:#e7efe8;border-radius:12px}.phase-head p{font-size:14px;color:var(--muted);margin:8px 0 0}.phase-summary{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:28px 0}.phase-summary .metric b{font-size:30px}.phase-summary .metric small{display:block;font-size:12px;color:var(--muted);margin-top:8px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:30px 0}.metric{padding:20px 24px;background:white;border:1px solid var(--line);border-radius:12px}.metric b{display:block;font-size:34px;line-height:1.2;color:var(--forest)}.metric span{font-size:12px;color:var(--muted)}.notice{padding:16px 20px;border-left:4px solid #ba8526;background:#fff7e8;border-radius:0 8px 8px 0;color:#644c20;font-size:13px}.rail{display:flex;gap:9px;flex-wrap:wrap;margin:26px 0 30px}.rail a{width:46px;height:41px;border:1px solid #d7dfda;background:white;color:#6c7c76;text-align:center;text-decoration:none;line-height:39px;border-radius:8px;font-weight:650;font-size:12px}.rail a.complete{background:#1c634a;color:white;border-color:#1c634a}.rail a.active{background:#fff4d9;border-color:#d9b76d;color:#76571b}.stage{margin:20px 0;padding:27px 30px;border:1px solid var(--line);border-radius:14px;background:white;scroll-margin-top:20px}.stage>header{display:flex;gap:17px;align-items:flex-start}.number{font-size:16px;font-weight:700;width:44px;min-width:44px;height:44px;line-height:44px;text-align:center;border-radius:50%;background:#eef1ef;color:#6a7d73}.complete .number{background:#dceee2;color:#16603d}.active .number{background:#fff0ce;color:#845b13}h2{font-size:23px;line-height:1.3;letter-spacing:-.4px;margin:0 0 7px}.badge{font-size:10px;letter-spacing:.8px;text-transform:uppercase;font-weight:750;color:#75827a}.complete .badge{color:#1a7049}.active .badge{color:#9a6817}.goal{font-size:16px;color:#4c6364;margin:19px 0}.columns{display:grid;grid-template-columns:1fr 1.25fr;gap:34px}h3{font-size:11px;letter-spacing:1.1px;text-transform:uppercase;color:#4d6b5f;margin:10px 0}ul{margin:10px 0 16px;padding-left:18px;font-size:13px}li{padding-left:2px;margin:7px 0}.checklist{padding:0;list-style:none}.check{display:flex;gap:9px}.check>span:first-child{font-size:17px;line-height:1.3;color:#9aa59d}.check.done>span:first-child{color:#247047}.check strong{font-size:10px;margin-right:4px;text-transform:uppercase;color:#79877f}.check.done strong{color:#287149}.evidence{overflow-wrap:anywhere;background:#f4f7f4;padding:12px 15px;margin:12px 0 0;border-radius:7px;font-size:12px;color:#536a61}.evidence strong{color:#315947;margin-right:6px}.foot{font-size:12px;color:var(--muted);margin-top:27px}.links{margin:30px 0 0;padding:22px 25px;background:#e7efe8;border-radius:12px}.links h2{font-size:18px}.links p{font-size:13px;margin-bottom:0}.key{font-size:12px;color:var(--muted)}@media(max-width:650px){.phase-summary{grid-template-columns:1fr}.phase-head{padding:20px}.wrap{padding:24px 16px 45px}.mast{margin-bottom:25px}.brand{font-size:20px}.mast a{font-size:11px}.summary{gap:8px}.metric{padding:15px}.metric b{font-size:28px}.metric span{font-size:11px}.stage{padding:22px 20px}.columns{grid-template-columns:1fr;gap:0}h2{font-size:21px}.goal{font-size:15px}.rail{gap:6px}.rail a{width:39px}.lead{font-size:17px}.number{width:36px;min-width:36px;height:36px;line-height:36px;font-size:14px}.stage>header{gap:12px}}@media print{body{background:white;font-size:10pt}.wrap{padding:0}.rail,.mast a{display:none}h1{font-size:28pt}.stage{break-inside:avoid;padding:15px;border-radius:0}.stage h2{font-size:16pt}.summary{margin:15px 0}.metric b{font-size:22pt}.notice{font-size:9pt}.foot{font-size:9pt}}
</style></head><body><main class="wrap"><div class="mast"><div class="brand">RescueRelay</div><a href="build-guide.html">Open the build guide →</a></div><p class="eyebrow">Implementation roadmap and acceptance gates</p><h1>RescueRelay project plan</h1><p class="lead">Twelve stages build the local web and mobile product. Five separately scoped stages add optional AI integrations. Completion means the acceptance evidence exists, not simply that the source has been written.</p><p class="author"><strong>Author: Krishna Kallamadi</strong> · <a href="https://www.linkedin.com/in/krishna-kishore-kallamadi-a22b498/">LinkedIn</a> · <a href="https://github.com/krish339-ai/RescueRelay">Public project repository</a></p>'''
    out+='<div class="phase-summary">'
    for phase in data['phases']:
        grouped=[s for s in stages if s['phase']==phase['id']]
        tally={status:sum(s['status']==status for s in grouped) for status in ('complete','active','pending')}
        out+=f'<div class="metric"><b>{tally["complete"]}/{len(grouped)}</b><span>{E(phase["title"])}</span><small>{tally["active"]} in progress · {tally["pending"]} pending</small></div>'
    out+=f'</div><div class="notice">{E(data["status_note"])} Status checkpoint: {E(data["updated"])}.</div><nav class="rail" aria-label="Jump to a stage">{navigation}</nav><p class="key">Green means accepted · amber means in progress · gray means pending. An unchecked gate is not represented as passed. <a href="#service-decisions">Review all 17 service decisions</a>.</p>'
    release=data.get('current_release')
    if release:
        pending=''.join(f'<li>{E(item)}</li>' for item in release['pending'])
        release_class = 'complete' if release['status'] == 'verified' else 'active'
        release_label = 'Recorded implementation checkpoint verified' if release['status'] == 'verified' else 'Current revision verification pending'
        remaining = f'<h3>Remaining release checks</h3><ul>{pending}</ul>' if pending else '<p>Recorded implementation acceptance checks are complete. Publication of this documentation closure is tracked separately.</p>'
        out+=f'<section id="current-release" class="stage {release_class}"><h2>{E(release["title"])}</h2><span class="badge">{release_label}</span><p>{E(release["scope"])}</p><p class="evidence">{E(release["evidence"])}</p>{remaining}<p>{E(release["boundary"])}</p></section>'
    out+=''.join(cards)
    out+='<section id="service-decisions" class="service-section"><h2>All 17 service decisions</h2><p>Selected runtime adapter sources are implemented and final mocked verification passed. The remaining services are explicit alternatives or deferred tools. This matrix preserves the original default-off release checkpoint. Later local configuration and bounded provider checks appear in the <a href="ai-local-validation-2026-11-07.md">7 November validation report</a>; see <a href="submission-readiness.html">submission readiness</a> for remaining work. Configuration alone does not prove a live workflow.</p>'+service_matrix_html()+'<p>Scroll horizontally on a narrow screen. Gates 13–16 cover the selected extension and gate 17 covers evidence, documentation and handoff. Deferred options require a new scoped decision; no accounts, compute, human tasks or external actions are activated by this plan.</p></section>'
    out+='''<div class="links"><h2>How the plan connects to the project</h2><p><a href="build-guide.html">Build guide</a> explains the implementation sequence and local workflow. <a href="ai-api-contract.md">Optional AI contract</a> defines the additional integration boundary. <a href="implementation-plan.md">Architecture plan</a> groups the same work into technical workstreams. <a href="verification.md">Verification record</a> preserves observed results and untested targets. <a href="RescueRelay-Project-Documentation.docx">Official documentation</a> covers the product and technical reference.</p></div><p class="foot">This is a local-first reference build with synthetic demonstration data and in-app notifications. Stage completion does not imply production readiness, live dispatch, food-safety certification, signed native applications, or app-store availability.</p></main></body></html>'''
    (ROOT/'project-plan.html').write_text(out,encoding='utf-8')
    print(ROOT/'project-plan.html')

if __name__=='__main__': render()
